7	} from "@unomed/react-native-matrix-sdk";
8	import { MatrixJotaiStore } from "../const/matrx-jotai-store";
9	import { MatrixAtoms } from "../jotai";
10	
11	export class MatrixCore {
12	  public static instance: ClientInterface | null = null;
13	  public static syncService: SyncServiceInterface | null = null;
14	
15	  /** Returns the client or throws if not initialized. Eliminates per-method null checks. */
16	  public static getClient(): ClientInterface {
17	    if (!MatrixCore.instance) {
18	      throw new Error("Matrix client is not initialized");
19	    }
20	    return MatrixCore.instance;
21	  }
22	
23	  /** Returns the room or throws. Use instead of getClient().getRoom() + manual null check. */
24	  public static getRoom(roomId: string): RoomInterface {
25	    const room = MatrixCore.getClient().getRoom(roomId);
26	    if (!room) throw new Error(`Room not found: ${roomId}`);
27	    return room;
28	  }
29	
